12	.pill{display:inline-flex;align-items:center;gap:6px}.plus{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;background:#7c3aed;border:2px solid #e9d5ff;font-size:16px;line-height:1}
13	#pause{position:fixed;top:8px;right:10px;width:46px;height:46px;border-radius:50%;border:3px solid #f2c14e;background:linear-gradient(#8b3fd9,#4a1386);color:#fff;font-weight:900;font-size:18px;pointer-events:auto}
14	.ab{position:fixed;bottom:18px;width:84px;height:84px;border-radius:50%;border:3px solid #f2c14e;background:radial-gradient(circle at 40% 35%,#b06cff,#5a1aa0 70%);color:#fff;font-weight:900;font-size:12px;line-height:1.05;text-align:center;pointer-events:auto;box-shadow:0 3px 10px #0007;padding:0}
