17	</style>
18	<script type="importmap">{"imports":{"three":"./node_modules/three/build/three.module.js","three/addons/":"./node_modules/three/examples/jsm/"}}</script>
19	</head><body>
20	<div id="hud"><div class="bar"><span class="pill">&#10084;&#65039; 5/5 <span class="plus">+</span></span><span class="pill"><span id="coins">&#129689; 1,420</span> <span class="plus">+</span></span><span class="pill">&#128142; <span id="gems">36</span> <span class="plus">+</span></span></div>
21	<div class="title" id="title">05 &middot; FLOW INTO THE CURRENT</div><div id="mission">&#129510; Rescue <b>5</b> lost socks &nbsp;<span id="slots"></span></div></div>
22	<div id="badge">Bubble Dash<br>Chamber</div><button id="pause" data-noswipe aria-label="pause">&#10074;&#10074;</button>
23	<button id="blast" class="ab" data-noswipe><span class="ic">&#129767;</span>Bubble<br>Blast<span class="cd"></span></button><button id="turbo" class="ab" data-noswipe><span class="ic">&#127744;</span>Turbo<br>Spin<span class="cd"></span></button><div id="pausedLay">Paused</div><div id="load">Building the washer&hellip;</div>
24	<script type="module">
25	// ======================================================================================================================================
26	// Rainbow round 40 - REFERENCE-LOCKED PHYSICAL SECTION: Bubble Dash Chamber -> golden arch -> Sock Rescue tunnel -> exit.
27	// Every piece of scenery is a connected 3D mesh built in Blender from the fitted layout (tools/reflock/blender_section.py -> section.glb).
28	// At load, the two approved pictures are BAKED once onto those meshes from the cameras fitted to them (depth-tested: a surface only takes
29	// a picture's pixel where that camera really saw it; the HUD / Benny / coins / socks / loose bubbles are masked out). The baked texture is
30	// world-anchored like any painted texture; where neither picture saw a surface (or saw it too small), a code material in the same style
31	// shows. Plain perspective camera (no depth curve, no projection, no camera-facing scenery planes, no screen overlays).
32	// Benny, swipes, coins = the shared game code (benny31.glb + paddling shader, tools/kit05/controls.js, swimfx.js).
33	// ======================================================================================================================================
34	import * as THREE from 'three';
35	import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
36	import { installControls } from './controls.js';
37	const q = new URLSearchParams(location.search);
38	for (const [k, v] of [['c_LANE', '0.3'], ['c_LAT_MAX', '0.36'], ['speed', '2.2']]) if (!q.has(k)) q.set(k, v);
39	const W = +(q.get('w') ?? innerWidth), H = +(q.get('h') ?? innerHeight);
40	const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
41	renderer.setPixelRatio(q.get('w') ? 1 : Math.min(2, devicePixelRatio)); renderer.setSize(W, H); document.body.appendChild(renderer.domElement);
42	const SEC = await (await fetch('section.json')).json(), T = SEC.tunnel, CH = SEC.chamber;
43	const V3 = (a) => new THREE.Vector3(a[0], a[1], a[2]);
44	const scene = new THREE.Scene(); scene.background = new THREE.Color(q.get('sentinel') ? 0x00ff00 : 0x1a0630);   // ?sentinel=1: holes show pure green
45	const camera = new THREE.PerspectiveCamera(SEC.fov, W / H, 0.03, 300); camera.rotation.order = 'YXZ';
46	const world = new THREE.Group(); world.name = 'world'; scene.add(world);
47	const lerp = (a, b, x) => a + (b - a) * x, sstep = (a, b, x) => { const k = Math.min(1, Math.max(0, (x - a) / (b - a))); return k * k * (3 - 2 * k); };
48	const DEG = Math.PI / 180;
49	
50	// ---------------- route = the painted river's centre line (fit_section.py), Benny's path ----------------
51	const RT = SEC.route; const RX = (z) => { const x = Math.min(Math.max((-z - RT.z0) / RT.ds, 0), RT.x.length - 1.001), i = Math.floor(x), f = x - i; return RT.x[i] + (RT.x[i + 1] - RT.x[i]) * f; };
52	const PB = V3(SEC.benny.bubble), PBS = V3(SEC.benny.sock), ZB0 = PB.z, S_SOCK = PB.z - PBS.z;
53	const zOf = (s) => ZB0 - s;
54	const at = (s, out) => { const z = zOf(s); return out.set(RX(z), 0, z); };
55	const frameAt = (s) => { const z = zOf(s), k = (RX(z - 0.05) - RX(z + 0.05)) / 0.1; const t = new THREE.Vector3(k, 0, -1).normalize(); return { t, r: new THREE.Vector3(-t.z, 0, t.x), n: new THREE.Vector3(0, 1, 0) }; };
