    const page = await ctx.newPage(); page.on('pageerror', (e) => errs.push(String(e).slice(0, 400))); page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text().slice(0, 400)); });
    const query = mode === 'stills' ? a3 : a3;
