        for (let i = 0; i < P.count; i += 7) { v.set(P.getX(i), P.getY(i), P.getZ(i), 1).applyMatrix4(o.matrixWorld).applyMatrix4(VP); n++; if (v.w > 0.05 && Math.abs(v.x / v.w) < 1 && Math.abs(v.y / v.w) < 1) inF++;
          uvmin = [Math.min(uvmin[0], UV.getX(i)), Math.min(uvmin[1], UV.getY(i))]; uvmax = [Math.max(uvmax[0], UV.getX(i)), Math.max(uvmax[1], UV.getY(i))]; }
