        const px = new Uint8Array(256 * 128 * 4); renderer.readRenderTargetPixels(rt, 0, 0, 256, 128, px); let cov = 0; for (let i = 3; i < px.length; i += 4) cov += px[i] > 0 ? 1 : 0;
        out[name] = { verts: P.count, idx: g.index ? g.index.count : null, inFrame: +(inF / n).toFixed(3), uvmin, uvmax, uvRasterCover: +(cov / (256 * 128)).toFixed(3), bbox: (g.computeBoundingBox(), [g.boundingBox.min.toArray().map((x) => +x.toFixed(2)), g.boundingBox.max.toArray().map((x) => +x.toFixed(2))]) }; }
