// Round 40: bake the section once (same code as the live bake) and save it for the app build: <out>/baked/*.png + manifest.json
//   node section_export.cjs <game folder> <out folder>
const { chromium } = require('playwright'); const { spawn } = require('child_process'); const fs = require('fs'); const path = require('path');
(async () => {
  const [dir, out] = process.argv.slice(2); const B = path.join(out, 'baked'); fs.mkdirSync(B, { recursive: true });
  const port = 9400 + Math.floor(Math.random() * 400); const srv = spawn('python3', ['-m', 'http.server', '--bind', '127.0.0.1', String(port)], { cwd: dir, stdio: 'ignore' }); await new Promise((r) => setTimeout(r, 1200));
  const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  try {
    const page = await (await browser.newContext({ viewport: { width: 412, height: 915 } })).newPage(); page.on('pageerror', (e) => console.log('ERR', e.message));
    await page.goto(`http://127.0.0.1:${port}/play3.html?w=412&h=915`); await page.waitForFunction(() => window.ready === true, null, { timeout: 1200000 });
    const names = await page.evaluate(() => window.bakeNames()); const man = { meshes: {}, foam: await page.evaluate(() => window.foamPainted()) }; const tpl = {};
    for (const n of names) { const e = await page.evaluate((n) => window.bakeExport(n), n); if (!e) continue; if (e.template) { tpl[n] = e.template; continue; }
      fs.writeFileSync(path.join(B, `${n}_bake.jpg`), Buffer.from(e.bake.split(',')[1], 'base64')); fs.writeFileSync(path.join(B, `${n}_den.png`), Buffer.from(e.den.split(',')[1], 'base64'));
      man.meshes[n] = { bake: `${n}_bake.jpg`, den: `${n}_den.png`, cov: e.cov }; }
    for (const [n, t] of Object.entries(tpl)) if (man.meshes[t]) man.meshes[n] = { ...man.meshes[t], template: t };
    fs.writeFileSync(path.join(B, 'manifest.json'), JSON.stringify(man)); console.log('exported', Object.keys(man.meshes).length, 'meshes,', man.foam.length, 'foam domes');
  } finally { await browser.close(); srv.kill(); }
})();
#!/usr/bin/env bash
# Round 40: put the reference-locked section INTO the Rainbow app build (public/section/ -> dist/section/ -> the Android APK).
#   bash tools/reflock/build_section_app.sh <workspace made by setup_section.sh>
# Self-contained static scene (three.js 0.180 vendored, no CDN), textures pre-baked once (section_export.cjs), no approved pictures shipped.
# The main game hands over to it between Screen 04 and Screen 05 only when built with VITE_RAINBOW_BONUS=1 (or opened with ?bonus=1):
# the default game is unchanged.
set -e
SRC=$(cd "$(dirname "$0")/../.." && pwd); WS=$(cd "${1:?workspace}" && pwd); G="$WS/section"; P="$SRC/public/section"
rm -rf "$WS/app"; NODE_PATH=$(npm root -g) node "$SRC/tools/reflock/section_export.cjs" "$G" "$WS/app"
rm -rf "$P"; mkdir -p "$P/vendor/three/build" "$P/vendor/three/examples/jsm/loaders" "$P/vendor/three/examples/jsm/utils" "$P/baked"
T=/tmp/rainbow_r34/node_modules/three
cp "$T/build/three.module.js" "$T/build/three.core.js" "$P/vendor/three/build/"; cp "$T/examples/jsm/loaders/GLTFLoader.js" "$P/vendor/three/examples/jsm/loaders/"; cp "$T/examples/jsm/utils/BufferGeometryUtils.js" "$P/vendor/three/examples/jsm/utils/"
cp "$WS/app/baked/"* "$P/baked/"
for f in section.glb section.json controls.js swimfx.js benny31.glb bake.png coin.png splash.png bubble.png glint.png; do cp -L "$G/$f" "$P/$f"; done
python3 - "$SRC/tools/reflock/section.html" "$P/index.html" <<'PY'
import sys
s = open(sys.argv[1]).read()
a = '"three":"./node_modules/three/build/three.module.js","three/addons/":"./node_modules/three/examples/jsm/"'
assert a in s; s = s.replace(a, '"three":"./vendor/three/build/three.module.js","three/addons/":"./vendor/three/examples/jsm/"')
a = "const q = new URLSearchParams(location.search);"; assert a in s
s = s.replace(a, a + "\nif (!q.has('w') && !q.has('play')) q.set('play', '1');   // app: real-time play\nif (!q.has('prebaked')) q.set('prebaked', '1');   // app: textures baked offline")
open(sys.argv[2], 'w').write(s)
PY
du -sh "$P" | cut -f1 | xargs echo "section in the app build:" "$P"
// Round 40: the reference-locked Bubble Dash -> Sock Rescue section (public/section/, built by tools/reflock/build_section_app.sh)
// as part of the Rainbow route between Screen 04 and Screen 05. OFF by default (the current game is unchanged); ON in a build made with
// VITE_RAINBOW_BONUS=1 (the Android test build) or with ?bonus=1. Benny swims from 04 into the section (coins carried over) and from the
// section's exit back into the game at the Screen 05 checkpoint (?resume=05).
const q = new URLSearchParams(typeof location !== 'undefined' ? location.search : '');
const env = (import.meta as unknown as { env?: Record<string, string | undefined> }).env ?? {};
export const BONUS_ROUTE = {
  enabled: env.VITE_RAINBOW_BONUS === '1' || q.get('bonus') === '1',
  resume: q.get('resume'),
  resumeCoins: Number(q.get('coins')),
  go(coins: number) { location.href = `section/index.html?return=1&bonus=1&coins=${Math.round(coins)}`; },
